//! 🔣️ Original JSON string syntax derives scalar bytes without a temporary owned text buffer.
use super::{RetainedWireUtf8Validation,RetainedWireByteSource};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(Clone,Copy)]
pub(crate) struct RetainedWireJsonStringSource{end:usize,scan:usize,decoded:usize,copy:usize,scalar:u32,width:u8,index:u8,validation:RetainedWireUtf8Validation}
impl RetainedWireJsonStringSource{
 fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
 pub(crate) fn new<S:RetainedWireByteSource+?Sized>(source:&S,range:(usize,usize))->Result<Self,ValueError>{if range.1.checked_sub(range.0).is_none_or(|width|width<2)||range.1>source.original_source_identity().extent||source.byte_at(range.0)!=Some(b'"')||source.byte_at(range.1-1)!=Some(b'"'){return Err(Self::fault("original JSON string is not exactly quoted"))}Ok(Self{end:range.1-1,scan:range.0+1,decoded:0,copy:range.0+1,scalar:0,width:0,index:0,validation:RetainedWireUtf8Validation::new()})}
 fn hex<S:RetainedWireByteSource+?Sized>(source:&S,position:usize,end:usize)->Result<u32,ValueError>{let finish=position.checked_add(4).filter(|finish|*finish<=end).ok_or_else(||Self::fault("original JSON unicode unit is truncated"))?;let mut value=0;for offset in position..finish{let byte=source.byte_at(offset).ok_or_else(||Self::fault("original JSON unicode unit escaped its range"))?;let digit=match byte{b'0'..=b'9'=>byte-b'0',b'a'..=b'f'=>byte-b'a'+10,b'A'..=b'F'=>byte-b'A'+10,_=>return Err(Self::fault("original JSON unicode unit is not hexadecimal"))};value=(value<<4)|u32::from(digit)}Ok(value)}
 fn escape<S:RetainedWireByteSource+?Sized>(source:&S,position:usize,end:usize)->Result<(u32,usize),ValueError>{let tag=source.byte_at(position+1).filter(|_|position+1<end).ok_or_else(||Self::fault("original JSON escape is truncated"))?;let scalar=match tag{b'"'=>u32::from(b'"'),b'\\'=>u32::from(b'\\'),b'/'=>u32::from(b'/'),b'b'=>8,b'f'=>12,b'n'=>10,b'r'=>13,b't'=>9,b'u'=>{let first=Self::hex(source,position+2,end)?;if(0xdc00..=0xdfff).contains(&first){return Err(Self::fault("original JSON has an isolated low surrogate"))}if(0xd800..=0xdbff).contains(&first){if source.byte_at(position+6)!=Some(b'\\')||source.byte_at(position+7)!=Some(b'u'){return Err(Self::fault("original JSON high surrogate has no original low unit"))}let second=Self::hex(source,position+8,end)?;if !(0xdc00..=0xdfff).contains(&second){return Err(Self::fault("original JSON surrogate pair is invalid"))}return Ok((0x10000+((first-0xd800)<<10)+(second-0xdc00),position+12))}return Ok((first,position+6))},_=>return Err(Self::fault("original JSON escape is invalid"))};Ok((scalar,position+2))}
 fn width(scalar:u32)->u8{if scalar<0x80{1}else if scalar<0x800{2}else if scalar<0x10000{3}else{4}}
 fn byte(scalar:u32,width:u8,index:u8)->u8{if width==1{return scalar as u8}if index==0{return match width{2=>0xc0|(scalar>>6)as u8,3=>0xe0|(scalar>>12)as u8,_=>0xf0|(scalar>>18)as u8}}0x80|((scalar>>(6*u32::from(width-index-1)))&63)as u8}
 pub(crate) fn decoded_extent(&self)->usize{self.decoded}
 pub(crate) fn scan_original_piece<S:RetainedWireByteSource+?Sized>(&mut self,source:&S)->Result<bool,ValueError>{for _ in 0..4096{if self.scan==self.end{if !self.validation.is_complete(){return Err(Self::fault("original JSON string contains truncated UTF8"))}return Ok(true)}let byte=source.byte_at(self.scan).filter(|_|self.scan<self.end).ok_or_else(||Self::fault("original JSON scan escaped its original source"))?;let length=if byte==b'\\'{if !self.validation.is_complete(){return Err(Self::fault("original JSON escape interrupts UTF8"))}let(scalar,next)=Self::escape(source,self.scan,self.end)?;self.scan=next;usize::from(Self::width(scalar))}else{if byte<32||byte==b'"'{return Err(Self::fault("original JSON text contains an unescaped control or quote"))}self.validation=self.validation.consume(&[byte])?;self.scan+=1;1};self.decoded=self.decoded.checked_add(length).ok_or_else(||Self::fault("original JSON output extent overflow"))?;}if self.scan==self.end{if !self.validation.is_complete(){return Err(Self::fault("original JSON string contains truncated UTF8"))}Ok(true)}else{Ok(false)}}
 pub(crate) fn copy_original_byte<S:RetainedWireByteSource+?Sized>(&mut self,source:&S)->Result<u8,ValueError>{if self.index<self.width{let byte=Self::byte(self.scalar,self.width,self.index);self.index+=1;return Ok(byte)}let byte=source.byte_at(self.copy).filter(|_|self.copy<self.end).ok_or_else(||Self::fault("original JSON derived output escaped its input"))?;if byte==b'\\'{let(scalar,next)=Self::escape(source,self.copy,self.end)?;self.copy=next;self.scalar=scalar;self.width=Self::width(scalar);self.index=1;Ok(Self::byte(scalar,self.width,0))}else{if byte<32||byte==b'"'{return Err(Self::fault("original JSON output contains an invalid raw byte"))}self.copy+=1;Ok(byte)}}
}
